import axios from 'axios';

export interface FigureData {
  src: string;
  title: string;
  caption?: string;
  observation?: string;
}

export interface AnalysisData {
  reportMarkdown: string;
  figures: FigureData[];
}

const ARTIFACTS_BASE = 'http://localhost:8000/artifacts/analysis';

// The known pool of potential analysis figures generated by the pipeline.
const CANDIDATE_FIGURES = [
  { filename: 'weight_evolution.png', title: 'Weight Evolution', caption: 'Evolution of adaptive weights across training rounds' },
  { filename: 'quality_vs_weight.png', title: 'Quality vs Weight', caption: 'Scatter plot of client quality vs assigned weights' },
  { filename: 'heatmap_weights.png', title: 'Weight Heatmap', caption: 'Heatmap of client weights across all rounds' },
  { filename: 'rarity_bonus_distribution.png', title: 'Rarity Bonus Distribution', caption: 'Distribution of class rarity multipliers' },
  { filename: 'gate_distribution.png', title: 'Gate Distribution', caption: 'Activations of the reliability gate' },
];

export const fetchAnalysisData = async (): Promise<AnalysisData> => {
  // 1. Fetch the markdown report
  let reportMarkdown = '';
  try {
    const reportRes = await axios.get(`${ARTIFACTS_BASE}/analysis_report.md`);
    reportMarkdown = reportRes.data;
  } catch (error) {
    throw new Error('Analysis report unavailable.');
  }

  // 2. Discover figures by checking their existence via HEAD requests
  const figures: FigureData[] = [];
  
  await Promise.all(CANDIDATE_FIGURES.map(async (candidate) => {
    const url = `${ARTIFACTS_BASE}/${candidate.filename}`;
    try {
      // Use a HEAD request to check if the file exists without downloading the full image in the service layer
      await axios.head(url);
      figures.push({
        src: url,
        title: candidate.title,
        caption: candidate.caption
      });
    } catch (e) {
      // If it 404s, the artifact simply wasn't generated in this run. We skip it.
    }
  }));

  if (!reportMarkdown && figures.length === 0) {
    throw new Error('No analysis artifacts found.');
  }

  // Sort figures to maintain a consistent display order based on the candidate list
  const sortedFigures = figures.sort((a, b) => {
    const idxA = CANDIDATE_FIGURES.findIndex(c => a.src.includes(c.filename));
    const idxB = CANDIDATE_FIGURES.findIndex(c => b.src.includes(c.filename));
    return idxA - idxB;
  });

  return {
    reportMarkdown,
    figures: sortedFigures
  };
};
